/*=========================================
Germination
=========================================*/
add(
  "agriculture",
  "crop_production",
  "Germination",
  `<h2>Germination</h2>
<h3> EXTENDED MASTER NOTES</h3>
<p>
Germination is the biological process by which a dormant seed resumes growth and develops into a seedling under favorable environmental conditions. It marks the beginning of the crop life cycle.
</p>
<h4> CONDITIONS FOR GERMINATION</h4>
<ul>
<li><b>Water (Moisture):</b> Softens the seed coat and activates enzymes.</li>
<li><b>Oxygen (Air):</b> Used in respiration to release energy for growth.</li>
<li><b>Warmth (Suitable Temperature):</b> Activates metabolic processes.</li>
</ul>
<h4> PROCESS OF GERMINATION</h4>
<ol>
<li>Seed absorbs water (imbibition)</li>
<li>Seed coat softens and splits</li>
<li>Enzymes are activated for food breakdown</li>
<li>Radicle (root) emerges first</li>
<li>Plumule (shoot) grows upward</li>
<li>Seedling establishes itself in soil</li>
</ol>
<h3> CONCEPT DIAGRAM</h3>
<pre>
Dormant Seed → Water Absorption → Enzyme Activation → Root → Shoot → Seedling
</pre>
<h3> IMPORTANCE OF GERMINATION</h3>
<ul>
<li>Starts plant life cycle</li>
<li>Ensures crop establishment</li>
<li>Determines final yield potential</li>
<li>Influenced by seed quality and environment</li>
</ul>
<h3> STEP-BY-STEP UNDERSTANDING</h3>
<ol>
<li>Seed absorbs moisture from soil</li>
<li>Stored food is converted into energy</li>
<li>Root emerges for anchorage and absorption</li>
<li>Shoot develops leaves for photosynthesis</li>
</ol>
<h3> KEY EXAM TIPS</h3>
<ul>
<li>Always mention the three conditions</li>
<li>Use correct biological terms like radicle and plumule</li>
<li>Explain processes step-by-step</li>
</ul>
`,
[
{
q: "1. Define germination.",
hint: "Think seed to seedling",
ans: "Germination is the process by which a seed develops into a seedling under favorable conditions.",
explain: "It marks the beginning of plant growth.",
why: "Core biology-based agriculture concept."
},
{
q: "2. State three conditions necessary for germination.",
hint: "Think environment factors",
ans: "Water, oxygen, and warmth.",
explain: "These conditions activate seed metabolism.",
why: "Frequently tested factual question."
},
{
q: "5. Why do seeds fail to germinate in dry soil?",
hint: "Think missing factor",
ans: "Because there is no water.",
explain: "Water is needed to activate seed growth processes.",
why: "Application-based environmental question."
}
]
);
