/*================================================
PLANT PHSIOLOGY AND IRRIGATION
=================================================*/
add(
  "agriculture",
  "plant_physiology",
  "Photosynthesis",
  `<h2>Photosynthesis</h2>
<h3> EXTENDED MASTER NOTES</h3>
<p>
Photosynthesis is the process by which green plants manufacture their own food (glucose) using sunlight energy, carbon dioxide, and water in the presence of chlorophyll found in chloroplasts.
</p>
<h4> OVERALL CHEMICAL EQUATION</h4>
<pre>
6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (in presence of light & chlorophyll)
</pre>
<h4> SITES OF PHOTOSYNTHESIS</h4>
<ul>
<li><b>Chloroplasts:</b> Contain chlorophyll, the green pigment that traps sunlight energy</li>
<li><b>Leaves:</b> Main site where photosynthesis occurs</li>
</ul>
<h4> STAGES OF PHOTOSYNTHESIS</h4>
<h5>1. Light-Dependent Stage</h5>
<ul>
<li>Takes place in chloroplasts</li>
<li>Requires sunlight</li>
<li>Water is split into hydrogen and oxygen</li>
<li>Oxygen is released as a by-product</li>
</ul>
<h5>2. Light-Independent Stage (Dark Reaction)</h5>
<ul>
<li>Does not require light directly</li>
<li>Uses carbon dioxide</li>
<li>Produces glucose (food)</li>
</ul>
<h4> FACTORS AFFECTING PHOTOSYNTHESIS</h4>
<ul>
<li>Light intensity</li>
<li>Carbon dioxide concentration</li>
<li>Temperature</li>
<li>Water availability</li>
<li>Chlorophyll content</li>
</ul>
<h4> IMPORTANCE OF PHOTOSYNTHESIS</h4>
<ul>
<li>Produces food (glucose) for plants</li>
<li>Releases oxygen into the atmosphere</li>
<li>Forms the base of all food chains</li>
<li>Supports crop growth and agricultural yield</li>
</ul>
<h3> STEP-BY-STEP UNDERSTANDING</h3>
<ol>
<li>Chlorophyll traps sunlight energy</li>
<li>Water is absorbed by roots and transported to leaves</li>
<li>Carbon dioxide enters leaves through stomata</li>
<li>Light energy converts raw materials into glucose</li>
<li>Oxygen is released as a by-product</li>
</ol>
<h3> KEY EXAM TIPS</h3>
<ul>
<li>Always mention chloroplast and chlorophyll in definitions</li>
<li>Memorize full equation (6CO₂ + 6H₂O)</li>
<li>Separate light-dependent and light-independent stages</li>
<li>Link photosynthesis to crop yield and food chains</li>
</ul>
`,
[
{
q: "1. Define photosynthesis.",
hint: "Think food production in plants",
ans: "Photosynthesis is the process by which green plants make food using sunlight, carbon dioxide, and water.",
explain: "It occurs in chloroplasts.",
why: "Core biology/agriculture definition."
},
{
q: "2. State four conditions necessary for photosynthesis.",
hint: "Think sunlight and gases",
ans: ["Sunlight", "Carbon dioxide", "Water", "Chlorophyll"],
explain: "These enable food production in plants.",
why: "Common recall question."
},
{
q: "5. Why do plants grow faster in sunlight?",
hint: "Think energy",
ans: "Because sunlight increases photosynthesis rate.",
explain: "More energy means more food production.",
why: "Reasoning question."
}
]
);
/*=========================================
Respiration in Plants
=========================================*/
add(
  "agriculture",
  "plant_physiology",
  "Respiration in Plants",
  `<h2>Respiration in Plants</h2>
<h3> EXTENDED MASTER NOTES</h3>
<p>
Respiration in plants is the biochemical process by which stored food (glucose) is broken down in the presence or absence of oxygen to release energy (ATP) needed for growth, development, and all cellular activities.
</p>
<h4> OVERALL CHEMICAL EQUATION (AEROBIC RESPIRATION)</h4>
<pre>
C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + Energy (ATP)
</pre>
<h4> SITE OF RESPIRATION</h4>
<ul>
<li>Occurs in all living plant cells</li>
<li>Mainly takes place in <b>mitochondria</b></li>
</ul>
<h4> TYPES OF RESPIRATION IN PLANTS</h4>
<h5>1. Aerobic Respiration</h5>
<ul>
<li>Uses oxygen</li>
<li>Produces large amount of energy (ATP)</li>
<li>Produces carbon dioxide and water</li>
</ul>
<h5>2. Anaerobic Respiration</h5>
<ul>
<li>Occurs without oxygen</li>
<li>Produces less energy</li>
<li>Produces ethanol and carbon dioxide (in some plant tissues)</li>
</ul>
<h4> RELATIONSHIP WITH PHOTOSYNTHESIS</h4>
<ul>
<li>Photosynthesis stores energy in glucose</li>
<li>Respiration releases that stored energy</li>
<li>Both processes are complementary</li>
</ul>
<h4> IMPORTANCE OF RESPIRATION</h4>
<ul>
<li>Provides energy for growth</li>
<li>Supports cell division and repair</li>
<li>Enables active transport in plants</li>
<li>Helps in synthesis of plant materials</li>
</ul>
<h3> STEP-BY-STEP UNDERSTANDING</h3>
<ol>
<li>Plant absorbs or uses stored glucose</li>
<li>Oxygen enters plant cells (for aerobic respiration)</li>
<li>Glucose is broken down in mitochondria</li>
<li>Energy (ATP) is released</li>
<li>Carbon dioxide and water are released as waste</li>
</ol>
<h3> KEY EXAM TIPS</h3>
<ul>
<li>Always mention ATP (energy currency)</li>
<li>Link respiration to mitochondria</li>
<li>Differentiate aerobic and anaerobic respiration</li>
<li>Explain relationship with photosynthesis</li>
</ul>
`,
[
{
q: "1. Define respiration in plants.",
hint: "Think energy release",
ans: "Respiration in plants is the process of breaking down food to release energy.",
explain: "Occurs in all living cells.",
why: "Core biology definition."
},
{
q: "2. Write the equation for aerobic respiration.",
hint: "Think glucose + oxygen",
ans: "C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + energy (ATP)",
explain: "Shows breakdown of glucose.",
why: "High-frequency exam question."
},
{
q: "5. Why do plants need oxygen?",
hint: "Think energy release",
ans: "Oxygen is needed for respiration.",
explain: "It helps break down glucose to release energy.",
why: "Reasoning question."
}
]
);
/*=========================================
Transpiration
=========================================*/
add(
  "agriculture",
  "plant_physiology",
  "Transpiration",
  `<h2>Transpiration</h2>
<h3> EXTENDED MASTER NOTES</h3>
<p>
Transpiration is the process by which water is lost from plant leaves in the form of water vapor, mainly through tiny openings called stomata.
It plays a major role in water movement, cooling, and nutrient transport in plants.
</p>
<h4> SITE OF TRANSPIRATION</h4>
<ul>
<li><b>Stomata:</b> Tiny pores on leaves (main site)</li>
<li><b>Cuticle:</b> Waxy layer on leaves</li>
<li><b>Lenticels:</b> Small openings in stems</li>
</ul>
<h4> TYPES OF TRANSPIRATION</h4>
<ul>
<li><b>Stomatal transpiration:</b> Occurs through stomata (most water loss)</li>
<li><b>Cuticular transpiration:</b> Through waxy cuticle</li>
<li><b>Lenticular transpiration:</b> Through lenticels in stems</li>
</ul>
<h4> TRANSPIRATION PULL (IMPORTANT CONCEPT)</h4>
<p>
As water evaporates from leaves, it creates a pulling force that draws more water upward from the roots through the xylem.
This is called <b>transpiration pull</b>.
</p>
<h4> COHESION-TENSION THEORY</h4>
<ul>
<li>Water molecules stick together (cohesion)</li>
<li>Water is pulled upward in a continuous column</li>
<li>Transpiration creates tension that pulls water up</li>
</ul>
<h4> IMPORTANCE OF TRANSPIRATION</h4>
<ul>
<li>Cools the plant by evaporation</li>
<li>Helps in absorption and transport of water</li>
<li>Transports minerals from roots to leaves</li>
<li>Maintains turgidity (plant firmness)</li>
</ul>
<h4> FACTORS AFFECTING TRANSPIRATION</h4>
<ul>
<li>Temperature (high increases rate)</li>
<li>Wind (removes water vapor faster)</li>
<li>Humidity (low humidity increases transpiration)</li>
<li>Light intensity (opens stomata)</li>
</ul>
<h4> REGULATION OF TRANSPIRATION</h4>
<ul>
<li>Stomata open and close to control water loss</li>
<li>Waxy cuticle reduces evaporation</li>
<li>Leaf adaptations reduce water loss in dry plants</li>
</ul>
<h3> STEP-BY-STEP UNDERSTANDING</h3>
<ol>
<li>Roots absorb water from soil</li>
<li>Water moves upward through xylem</li>
<li>Reaches leaves via veins</li>
<li>Evaporates through stomata</li>
<li>Creates transpiration pull for continuous water movement</li>
</ol>
<h3> KEY EXAM TIPS</h3>
<ul>
<li>Always mention stomata in definitions</li>
<li>Include transpiration pull in advanced answers</li>
<li>Differentiate types of transpiration</li>
<li>Link to water and mineral transport</li>
</ul>
`,
[
{
q: "1. Define transpiration.",
hint: "Think water loss",
ans: "Transpiration is the loss of water vapor from plant leaves through stomata.",
explain: "Mainly occurs in leaves.",
why: "Core definition question."
},
{
q: "2. Name three sites of transpiration.",
hint: "Think openings",
ans: ["Stomata", "Cuticle", "Lenticels"],
explain: "These allow water loss.",
why: "Recall question."
},
{
q: "5. Why is transpiration important?",
hint: "Think transport and cooling",
ans: "It helps in water movement and cooling.",
explain: "Also transports minerals.",
why: "Reasoning question."
}
]
);
/*=========================================
Nutrient Uptake
=========================================*/
add(
  "agriculture",
  "plant_physiology",
  "Nutrient Uptake",
  `<h2>Nutrient Uptake</h2>
<h3> EXTENDED MASTER NOTES</h3>
<p>
Nutrient uptake is the process by which plants absorb essential mineral nutrients from the soil through their roots, mainly via root hairs.
These nutrients are absorbed in dissolved form from soil water.
</p>

<h4> HOW NUTRIENTS ENTER THE PLANT</h4>
<ul>
<li><b>Root hairs:</b> Increase surface area for absorption</li>
<li><b>Soil solution:</b> Nutrients dissolve in water</li>
<li><b>Cell membranes:</b> Control entry of minerals into roots</li>
</ul>
<h4> MECHANISMS OF NUTRIENT UPTAKE</h4>
<ul>
<li><b>Diffusion:</b> Movement of nutrients from high concentration in soil to low concentration in root cells</li>
<li><b>Active transport:</b> Energy is used to absorb nutrients against concentration gradient</li>
</ul>
<h4> ADAPTATIONS OF ROOT HAIRS</h4>
<ul>
<li>Large surface area for absorption</li>
<li>Thin walls for easy diffusion</li>
<li>Many in number for efficiency</li>
</ul>
<h4> IMPORTANT PLANT NUTRIENTS</h4>
<ul>
<li><b>Macronutrients:</b> Nitrogen (N), Phosphorus (P), Potassium (K)</li>
<li><b>Micronutrients:</b> Iron (Fe), Zinc (Zn), Magnesium (Mg)</li>
</ul>
<h4> DEFICIENCY EFFECTS</h4>
<ul>
<li>Yellowing leaves (Nitrogen deficiency)</li>
<li>Poor root development (Phosphorus deficiency)</li>
<li>Weak stems (Potassium deficiency)</li>
</ul>
<h4> IMPORTANCE OF NUTRIENT UPTAKE</h4>
<ul>
<li>Supports plant growth and development</li>
<li>Prevents nutrient deficiency diseases</li>
<li>Improves crop yield and quality</li>
<li>Maintains healthy metabolic processes</li>
</ul>
<h3> STEP-BY-STEP UNDERSTANDING</h3>
<ol>
<li>Nutrients dissolve in soil water</li>
<li>Root hairs absorb mineral ions</li>
<li>Nutrients enter root cells via diffusion or active transport</li>
<li>Minerals move into xylem vessels</li>
<li>Nutrients are transported to different plant parts</li>
</ol>
<h3> KEY EXAM TIPS</h3>
<ul>
<li>Always mention root hairs in definitions</li>
<li>Include diffusion + active transport</li>
<li>Link nutrients to deficiency symptoms</li>
<li>Explain movement into xylem</li>
</ul>
`,
[
{
q: "1. Define nutrient uptake.",
hint: "Think absorption by roots",
ans: "Nutrient uptake is the absorption of mineral nutrients from the soil by plant roots.",
explain: "Occurs mainly through root hairs.",
why: "Core definition question."
},
{
q: "2. Name two mechanisms of nutrient uptake.",
hint: "Think movement processes",
ans: ["Diffusion", "Active transport"],
explain: "Nutrients enter roots through these processes.",
why: "Basic recall question."
},
{
q: "5. Why do nutrient deficiencies affect growth?",
hint: "Think plant functions",
ans: "Because nutrients are needed for growth processes.",
explain: "Without nutrients, metabolism slows.",
why: "Reasoning question."
}
]
);
/*=========================================
Factors Affecting Plant Growth
=========================================*/
add(
  "agriculture",
  "plant_physiology",
  "Factors Affecting Plant Growth",
  `<h2>Factors Affecting Plant Growth</h2>
<h3> EXTENDED MASTER NOTES</h3>
<p>
Plant growth is influenced by a combination of environmental (external) and internal factors that determine how well a plant develops, produces food, and yields crops.
</p>

<h4> EXTERNAL FACTORS (ENVIRONMENTAL)</h4>
<ul>
<li><b>Light:</b> Needed for photosynthesis and energy production</li>
<li><b>Water:</b> Essential for nutrient transport and cell turgidity</li>
<li><b>Soil nutrients:</b> Provide minerals for growth and development</li>
<li><b>Temperature:</b> Affects enzyme activity and metabolic rate</li>
<li><b>Soil type:</b> Determines aeration, drainage, and nutrient availability</li>
<li><b>Carbon dioxide:</b> Required for photosynthesis</li>
</ul>

<h4> INTERNAL FACTORS</h4>
<ul>
<li><b>Genetics:</b> Determines growth potential and crop type</li>
<li><b>Plant hormones:</b> Control growth and development processes</li>
</ul>
<h4> LIMITING FACTOR PRINCIPLE</h4>
<p>
Plant growth is controlled by the factor that is in the shortest supply. Even if all other conditions are ideal, a single limiting factor can reduce growth.
</p>

<h4> EFFECTS OF DEFICIENCY</h4>
<ul>
<li>Low light → weak growth and poor photosynthesis</li>
<li>Low water → wilting and reduced nutrient transport</li>
<li>Low nutrients → stunted growth</li>
<li>Extreme temperatures → enzyme damage or inactivity</li>
</ul>

<h4> IMPORTANCE OF OPTIMAL CONDITIONS</h4>
<ul>
<li>Ensures maximum photosynthesis</li>
<li>Improves crop yield and quality</li>
<li>Supports healthy root and shoot development</li>
<li>Enhances resistance to stress and disease</li>
</ul>

<h3> STEP-BY-STEP UNDERSTANDING</h3>
<ol>
<li>Plant absorbs resources from environment</li>
<li>Internal systems process nutrients and energy</li>
<li>Growth depends on availability of all key factors</li>
<li>Limiting factor restricts full growth potential</li>
<li>Balanced conditions result in maximum yield</li>
</ol>
<h3> KEY EXAM TIPS</h3>
<ul>
<li>Always separate internal and external factors</li>
<li>Include limiting factor principle in essays</li>
<li>Link all factors to photosynthesis and growth</li>
<li>Use cause-effect reasoning in explanations</li>
</ul>
`,
[
{
q: "1. List four factors affecting plant growth.",
hint: "Think environment",
ans: ["Light", "Water", "Nutrients", "Temperature"],
explain: "These are essential environmental conditions.",
why: "Basic recall question."
},
{
q: "2. Why is light important?",
hint: "Think food production",
ans: "It is used in photosynthesis.",
explain: "It enables plants to make food.",
why: "Application question."
},
{
q: "3. What is a limiting factor?",
hint: "Think shortage",
ans: "It is the factor in shortest supply that limits growth.",
explain: "It controls plant growth rate.",
why: "Concept question."
},
{
q: "5. Why do plants grow poorly in extreme temperatures?",
hint: "Think enzymes",
ans: "Because enzymes stop working properly.",
explain: "Affects metabolism.",
why: "Reasoning question."
}
]
);
