/*=========================================
Risk and Uncertainty in Farming
=========================================*/
add(
  "agriculture",
  "farm_management",
  "Risk and Uncertainty",
  `<h2>Risk and Uncertainty in Farming</h2>
<h3> DEEP NOTES</h3>
<p>
Risk in farming refers to the possibility of financial loss resulting from uncertain or unpredictable events that affect agricultural production, prices, or income.
Uncertainty in this context means situations where outcomes cannot be known in advance with certainty.
</p>
<hr>
<h3> SOURCES OF RISK IN FARMING</h3>
<ul>
<li>
<b>Weather-related risks:</b> Droughts, floods, irregular rainfall, hailstorms, excessive heat or cold.
</li>
<li>
<b>Pest and disease risks:</b> Attacks by insects, fungi, bacteria, or viruses that destroy crops or harm livestock.
</li>
<li>
<b>Market risks:</b> Fluctuations in market prices, changes in demand, competition from other producers.
</li>
<li>
<b>Natural disasters:</b> Events such as earthquakes, landslides, or wildfires that destroy farm property.
</li>
<li>
<b>Storage and post-harvest risks:</b> Losses during storage due to spoilage, pests, or poor handling.
</li>
</ul>
<hr>
<h3> RISK MANAGEMENT METHODS</h3>
<ul>
<li>
<b>Diversification:</b> Growing different types of crops or raising various types of livestock to reduce dependence on a single source.
</li>
<li>
<b>Crop insurance:</b> Protecting against losses due to crop failure caused by weather or pests.
</li>
<li>
<b>Proper storage and preservation:</b> Using appropriate methods to store farm produce and minimize spoilage.
</li>
<li>
<b>Resistant crop varieties:</b> Planting crops that are naturally resistant to common pests and diseases.
</li>
<li>
<b>Good farm planning and timing:</b> Making informed decisions about planting, harvesting, and marketing to minimize risks.
</li>
</ul>
<hr>
`,
[
  {
    q: "What is risk in farming?",
    hint: "Think possible loss due to uncertainty",
    ans: "Possibility of loss due to uncertain factors",
    explain: "Risk refers to situations where farming outcomes may lead to losses because of unpredictable events.",
    why: "Because agriculture depends on natural and market conditions that are not fully controllable."
  },
  {
    q: "Name sources of risk in farming",
    hint: "Think weather, pests, and markets",
    ans: ["Weather", "Pests", "Diseases", "Market changes"],
    explain: "These are major factors that can negatively affect farm output and income.",
    why: "Because they directly influence production and profitability."
  },
  {
    q: "What is the difference between risk and uncertainty?",
    hint: "Think predictable vs unpredictable",
    ans: "Risk can be estimated, uncertainty cannot",
    explain: "Risk involves known probabilities while uncertainty has unknown outcomes.",
    why: "Because some farming events can be predicted while others cannot."
  }
]
);
