add(
  "agriculture",
  "crop_production_systems",
  "Crop Harvesting (Exam Master Notes)",
  `<h2>Crop Harvesting</h2>
<h3> PEST LIFE CYCLE (DETAILED NOTES)</h3>
<p>
The pest life cycle refers to the sequence of stages that a pest undergoes as it grows and develops from its early form to a fully mature adult. Understanding this cycle is essential in agriculture because it helps farmers identify the most vulnerable stage of the pest for effective control.
</p>
<p>
Most insect pests undergo complete metamorphosis, which involves four main stages: egg, larva, pupa, and adult. Each stage has unique characteristics and impacts on crops.
</p>
<hr>
<h3> STAGES OF PEST LIFE CYCLE</h3>
<p><b>1. Egg Stage</b></p>
<p>
This is the first stage where pests begin their life. Eggs are usually laid on plant surfaces such as leaves, stems, or in the soil. At this stage, pests are inactive but developing.
</p>
<p><b>2. Larva Stage</b></p>
<p>
This is the most active and destructive stage of the pest life cycle. Larvae feed heavily on crops, causing significant damage to leaves, stems, and roots.
</p>
<p><b>3. Pupa Stage</b></p>
<p>
This is a transformation stage where the pest changes from larva to adult. During this stage, the pest is usually inactive and enclosed in a protective covering such as a cocoon or chrysalis.
</p>
<p><b>4. Adult Stage</b></p>
<p>
This is the fully developed stage of the pest. Adult pests reproduce and lay eggs, continuing the life cycle. Some adults may also feed on crops, but their main role is reproduction and spread.
</p>
<h3> IMPORTANCE OF UNDERSTANDING PEST LIFE CYCLE</h3>
<ul>
<li>Helps identify the most vulnerable stage for control</li>
<li>Improves timing of pest control measures</li>
<li>Reduces crop damage and losses</li>
<li>Enhances effectiveness of pest management strategies</li>
</ul>
<h3> SUMMARY</h3>
<ul>
<li>Pests pass through four stages: egg, larva, pupa, adult</li>
<li>Larva stage causes the most damage to crops</li>
<li>Effective pest control depends on correct timing</li>
<li>Understanding the life cycle improves farm productivity</li>
</ul>
`,
[
  {
    q: "What is harvesting?",
    hint: "Think collecting mature crops",
    ans: "It is the process of collecting mature crops from the field.",
    explain: "Crops are removed from the field when they are fully grown.",
    why: "Because crops must be harvested at the right time for best quality."
  },

  {
    q: "Name harvesting methods.",
    hint: "Think human and machine methods",
    ans: ["Manual harvesting", "Mechanical harvesting"],
    explain: "Crops can be collected using human labor or machines.",
    why: "Because different farm sizes require different harvesting methods."
  },

  {
    q: "Why is harvesting important?",
    hint: "Think food and quality",
    ans: "It ensures food availability and maintains crop quality.",
    explain: "Harvesting at the right time prevents spoilage and losses.",
    why: "Because crops must be collected when mature for best results."
  }
]
);
