/*=========================================
Wind and Humidity Effects
=========================================*/
add(
  "agriculture",
  "environmental_factors",
  "Wind and Humidity Effects",
  `<h2>Wind and Humidity Effects</h2>
<h2> WIND AND HUMIDITY IN AGRICULTURE</h2>
<h3> OVERVIEW</h3>
<p>
Wind and humidity are important climatic factors that influence crop growth, reproduction, water loss, and the spread of pests and diseases. Their effects can be both beneficial and harmful depending on their intensity and duration.
</p>
<hr>
<h3> EFFECTS OF WIND ON AGRICULTURE</h3>
<h4> POSITIVE EFFECTS OF WIND</h4>
<ul>
<li><b>Pollination:</b> Wind helps transfer pollen in wind-pollinated crops.</li>
<li><b>Seed dispersal:</b> It helps spread seeds over large areas, aiding plant reproduction.</li>
</ul>
<h4> NEGATIVE EFFECTS OF WIND</h4>
<ul>
<li><b>Physical damage:</b> Strong winds can break stems, flatten crops, or uproot plants.</li>
<li><b>Increased water loss:</b> Wind increases evaporation and transpiration, drying out plants faster.</li>
<li><b>Spread of pests and diseases:</b> Wind carries spores, insects, and pathogens from one field to another.</li>
</ul>
<h3> EFFECTS OF HUMIDITY ON CROPS</h3>
<h4> HIGH HUMIDITY</h4>
<ul>
<li>Promotes fungal and bacterial diseases</li>
<li>Slows down evaporation from leaves</li>
</ul>
<h4> LOW HUMIDITY</h4>
<ul>
<li>Increases water loss through transpiration</li>
<li>Causes wilting and reduced plant growth</li>
</ul>
<h3> SUMMARY OF EFFECTS</h3>
<h4> WIND</h4>
<ul>
<li>Supports pollination in some crops</li>
<li>Helps seed dispersal</li>
<li>Can cause crop damage and spread diseases</li>
</ul>
<h4> HUMIDITY</h4>
<ul>
<li>High humidity → increases disease risk</li>
<li>Low humidity → causes dehydration and wilting</li>
</ul>
`,
[
  {
    q: "How does wind affect agriculture?",
    hint: "Think pollination and damage",
    ans: "It helps pollination but can also damage crops and spread pests",
    explain: "Wind can aid in pollination for some crops but also cause physical damage, soil erosion, and spread of pests and diseases.",
    why: "Because wind directly influences plant reproduction, crop structure, and disease movement."
  },

  {
    q: "What is the effect of humidity on crops?",
    hint: "Think diseases and water loss",
    ans: "High humidity increases disease risk while low humidity causes drying",
    explain: "Humidity affects the amount of moisture in the air around plants, influencing growth conditions and disease development.",
    why: "Because plant health depends on balanced moisture levels in the environment."
  },

  {
    q: "How can strong winds damage crops?",
    hint: "Think physical force",
    ans: "They can break stems and uproot plants",
    explain: "Strong winds exert force on plants causing lodging or breaking of stems and branches.",
    why: "Because physical damage reduces crop yield and quality."
  },

  {
    q: "Why is humidity important for plant diseases?",
    hint: "Think fungi growth",
    ans: "It supports the growth of fungal diseases",
    explain: "High moisture in the air creates favorable conditions for fungi and bacteria.",
    why: "Because pathogens thrive in moist environments."
  }
]
);
/*=========================================
Climate Change and Farming
=========================================*/
add(
  "agriculture",
  "environmental_factors",
  "Climate Change and Farming",
  `<h2>Climate Change and Farming</h2>
<h2> CLIMATE CHANGE AND AGRICULTURE</h2>
<h3> OVERVIEW</h3>
<p>
Climate change refers to long-term shifts in temperature, rainfall patterns, wind systems, and other weather conditions that affect natural ecosystems and agricultural production.
</p>
<p>
These changes are mainly caused by both natural processes and human activities such as deforestation and pollution, and they significantly influence farming systems worldwide.
</p>
<h3> HOW CLIMATE CHANGE AFFECTS FARMING</h3>

<h4> 1. Disruption of Rainfall Patterns</h4>
<p>
Unpredictable rainfall makes it difficult for farmers to plan planting and harvesting seasons.
</p>

<h4> 2. Increased Temperatures</h4>
<p>
Higher temperatures increase evaporation, reduce soil moisture, and stress crops.
</p>

<h4> 3. Increased Pests and Diseases</h4>
<p>
Warmer conditions allow pests and diseases to survive and multiply faster.
</p>

<h4> 4. Extreme Weather Events</h4>
<p>
Events such as floods, droughts, and storms destroy crops and livestock systems.
</p>

<p><b>Example:</b> Heavy floods can destroy maize fields in low-lying areas before harvest.</p>

<hr>

<h3> EFFECTS OF CLIMATE CHANGE ON AGRICULTURE</h3>

<h4> 1. Droughts</h4>
<p>
Long periods without rainfall reduce soil moisture and lead to poor crop growth or total failure.
</p>
<h4> 2. Floods</h4>
<p>
Excess rainfall causes waterlogging, soil erosion, and destruction of crops.
</p>
<h4> 3. Reduced Agricultural Yields</h4>
<p>
Unstable weather patterns reduce productivity and food production.
</p>
<h4> 4. Pest and Disease Outbreaks</h4>
<p>
Changing temperatures increase pest survival and spread.
</p>
<h3> ADAPTATION METHODS</h3>

<ul>
<li>Drought-resistant crop varieties</li>
<li>Irrigation systems for dry areas</li>
<li>Agroforestry (planting trees with crops)</li>
<li>Weather forecasting and early warning systems</li>
<li>Soil conservation practices</li>
</ul>
`,
[
  {
    q: "What is climate change?",
    hint: "Think long-term weather changes",
    ans: "It is long-term changes in weather patterns affecting agriculture and the environment",
    explain: "Climate change refers to persistent changes in temperature, rainfall, and seasonal patterns over long periods of time.",
    why: "Because these changes directly affect crop growth, livestock productivity, and farming systems."
  },

  {
    q: "Give effects of climate change on farming",
    hint: "Think drought, floods, pests",
    ans: ["Drought", "Floods", "Reduced yields", "Pest outbreaks"],
    explain: "Climate change disrupts normal weather patterns, leading to extreme conditions that affect agriculture.",
    why: "Because crops and animals depend on stable environmental conditions to thrive."
  },

  {
    q: "How does drought affect agriculture?",
    hint: "Think water shortage",
    ans: "It reduces crop growth and yields",
    explain: "Lack of water leads to plant wilting, poor germination, and crop failure.",
    why: "Because water is essential for all stages of plant growth."
  },

  {
    q: "Why do pests increase with climate change?",
    hint: "Think temperature changes",
    ans: "Warmer conditions favor pest reproduction",
    explain: "Higher temperatures can increase the survival and breeding rate of pests.",
    why: "Because pests thrive in unstable and warmer environments."
  }
]
);
